
"use strict";
/* EmeraldOS Gold 2.0 - Support, Store, Staff Verification, User Friendliness */
(function(){
const PREFIX="gold20_";
const BUILD={name:"EmeraldOS Gold 2.0",version:"2.0",cloudPath:"gold20/current"};
const APP_DEFS=[{"id": "explorer", "name": "Gold Explorer", "category": "Files", "description": "Drive-style file manager", "logo": "app-logos/explorer.svg"}, {"id": "office", "name": "Gold Office", "category": "Productivity", "description": "Docs, Sheets, Slides and Forms", "logo": "app-logos/office.svg"}, {"id": "mail", "name": "Gold Mail", "category": "Communication", "description": "Internal mail", "logo": "app-logos/mail.svg"}, {"id": "chat", "name": "Gold Chat", "category": "Communication", "description": "Rooms and messages", "logo": "app-logos/chat.svg"}, {"id": "people", "name": "People", "category": "Communication", "description": "Contacts and users", "logo": "app-logos/people.svg"}, {"id": "support", "name": "Support Center", "category": "Support", "description": "Tickets and remote help", "logo": "app-logos/support.svg"}, {"id": "store", "name": "Gold Store", "category": "Apps", "description": "Install staff verified apps", "logo": "app-logos/store.svg"}, {"id": "settings", "name": "Settings", "category": "System", "description": "Customize Gold", "logo": "app-logos/settings.svg"}, {"id": "personalization", "name": "Personalization", "category": "System", "description": "Themes and backgrounds", "logo": "app-logos/personalization.svg"}, {"id": "staff", "name": "Staff Center", "category": "Staff", "description": "Staff-only control tools", "logo": "app-logos/staff.svg"}, {"id": "remote", "name": "Remote Assist", "category": "Support", "description": "Request/live remote help", "logo": "app-logos/remote.svg"}, {"id": "security", "name": "Security Center", "category": "System", "description": "Security and privacy", "logo": "app-logos/security.svg"}, {"id": "restore", "name": "Restore Center", "category": "System", "description": "Backup and restore", "logo": "app-logos/restore.svg"}, {"id": "update", "name": "Update Center", "category": "System", "description": "Gold updates", "logo": "app-logos/update.svg"}, {"id": "notepad", "name": "Notepad", "category": "Accessories", "description": "Simple text editor", "logo": "app-logos/notepad.svg"}, {"id": "calculator", "name": "Calculator", "category": "Accessories", "description": "Calculator", "logo": "app-logos/calculator.svg"}, {"id": "todo", "name": "Gold To Do", "category": "Productivity", "description": "Tasks and reminders", "logo": "app-logos/todo.svg"}, {"id": "calendar", "name": "Calendar", "category": "Productivity", "description": "Events", "logo": "app-logos/calendar.svg"}, {"id": "photos", "name": "Photos", "category": "Media", "description": "Photo board", "logo": "app-logos/photos.svg"}, {"id": "paint", "name": "Gold Paint", "category": "Creative", "description": "Sketch pad", "logo": "app-logos/paint.svg"}, {"id": "weather", "name": "Weather", "category": "Info", "description": "Weather placeholder", "logo": "app-logos/weather.svg"}, {"id": "clock", "name": "Alarms & Clock", "category": "Accessories", "description": "Clock and timers", "logo": "app-logos/clock.svg"}, {"id": "feedback", "name": "Feedback Hub", "category": "Support", "description": "Send feedback", "logo": "app-logos/feedback.svg"}, {"id": "help", "name": "Help", "category": "Support", "description": "Help and support", "logo": "app-logos/help.svg"}, {"id": "bios", "name": "BIOS Options", "category": "System", "description": "Emerald Systems BIOS A1", "logo": "app-logos/bios.svg"}, {"id": "dos", "name": "Emerald DOS", "category": "System", "description": "DOS terminal", "logo": "app-logos/dos.svg"}];
const STORE_SEED=[{"id": "budget", "name": "Gold Budget Planner", "category": "Productivity", "description": "Track budgets, categories, and totals.", "staffVerified": true, "author": "Emerald Systems Staff", "version": "1.0"}, {"id": "project-board", "name": "Gold Project Board", "category": "Productivity", "description": "Kanban board for projects and assignments.", "staffVerified": true, "author": "Emerald Systems Staff", "version": "1.0"}, {"id": "study-cards", "name": "Gold Study Cards", "category": "Education", "description": "Flashcards and study helper.", "staffVerified": false, "author": "Community", "version": "1.0"}, {"id": "inventory", "name": "Gold Inventory", "category": "Business", "description": "Inventory tracker with search and exports.", "staffVerified": true, "author": "Gold Staff", "version": "1.2"}, {"id": "site-checklist", "name": "Website Checklist", "category": "Developer", "description": "Launch checklist for sites and apps.", "staffVerified": false, "author": "Community", "version": "1.0"}, {"id": "ticket-desk", "name": "Ticket Desk", "category": "Support", "description": "Local ticket helper and report builder.", "staffVerified": true, "author": "Emerald Systems Staff", "version": "2.0"}];
let z=2000, activeWin=null, drag=null, resize=null, fb=null, workspaceTimer=null;
const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>\'"]/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;","\"":"&quot;"}[m]));
const uid=()=>"g"+Math.random().toString(36).slice(2,9)+Date.now().toString(36).slice(-5);
const now=()=>new Date().toISOString();
const username=()=>localStorage.getItem(PREFIX+"username")||localStorage.getItem("username")||"GoldUser";
const userRole=()=>String(localStorage.getItem(PREFIX+"role")||localStorage.getItem("role")||"user").toLowerCase();
const isStaff=()=>localStorage.getItem(PREFIX+"staffVerified")==="true" || ["admin","administrator","moderator","mod","operator","staff","executive","owner","network administrator","vip"].includes(userRole());
const appById=id=>APP_DEFS.find(a=>a.id===id)||APP_DEFS[0];
function read(k,f){try{return JSON.parse(localStorage.getItem(k)??JSON.stringify(f));}catch{return f}}
function write(k,v){localStorage.setItem(k,JSON.stringify(v));return v}
function saveText(name,text,type="text/plain"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),700)}
function bytes(v){return new Blob([typeof v==="string"?v:JSON.stringify(v)]).size}
function fmtBytes(n){if(!n)return"0 B";if(n<1024)return n+" B";if(n<1048576)return(n/1024).toFixed(1)+" KB";return(n/1048576).toFixed(2)+" MB"}
async function initFirebase(){try{fb=await import("./firebase.js");return fb;}catch(e){console.warn("Firebase unavailable",e);return null;}}
function defaultPrefs(){return {theme:"light",accent:"#0078d4",background:"gold",customBackground:"",bgMode:"cover",iconSize:"normal",density:"comfortable",labels:true,taskbarSearch:true,taskbarStaff:true,taskbarSupport:true,notifications:true,clockSeconds:false,highContrast:false,bigText:false,reducedMotion:false,desktopApps:["explorer","office","mail","support","store","settings","personalization","staff","remote","security","restore"]}}
function prefs(){return {...defaultPrefs(),...read(PREFIX+"prefs",{})}}
function setPrefs(p){write(PREFIX+"prefs",{...prefs(),...p});applyPrefs();renderDesktop();renderTaskbarExtras();saveWorkspaceDebounced();}
function applyPrefs(){const p=prefs();document.body.classList.toggle("dark",p.theme==="dark");document.body.classList.toggle("highcontrast",p.theme==="highcontrast"||p.highContrast);document.body.classList.toggle("bigtext",!!p.bigText);document.body.classList.toggle("no-motion",!!p.reducedMotion);document.body.classList.toggle("no-labels",!p.labels);document.documentElement.style.setProperty("--accent",p.accent||"#0078d4");document.documentElement.style.setProperty("--iconSize",p.iconSize==="large"?"86px":p.iconSize==="small"?"58px":"70px"); if(p.customBackground){document.body.classList.add("custom-bg");document.body.style.setProperty("--customBg",`url(${p.customBackground})`);document.body.style.setProperty("--bgMode",p.bgMode||"cover");} else {document.body.classList.remove("custom-bg");document.body.style.removeProperty("--customBg");let w="linear-gradient(135deg,#eff6ff 0%,#dbeafe 38%,#fff7d6 100%)";if(p.background==="blue")w="linear-gradient(135deg,#dbeafe,#bfdbfe,#ffffff)";if(p.background==="emerald")w="linear-gradient(135deg,#d1fae5,#ecfdf5,#fef3c7)";if(p.background==="slate")w="linear-gradient(135deg,#e2e8f0,#f8fafc,#dbeafe)";if(p.background==="dark")w="linear-gradient(135deg,#111827,#172554,#312e81)";document.documentElement.style.setProperty("--wallpaper",w);} }
function notifications(){return read(PREFIX+"notifications",[])}function saveNotifications(n){write(PREFIX+"notifications",n);renderNotifBadge();}
function notify(title,body,app="System",persist=true){if(!prefs().notifications)return;const n={id:uid(),title,body,app,time:now(),read:false};if(persist)saveNotifications([n,...notifications()].slice(0,80));renderToast(n);}
function renderToast(n){const d=document.createElement("div");d.className="toast";d.innerHTML=`<b>${esc(n.title)}</b><p>${esc(n.body)}</p>`;Object.assign(d.style,{position:"fixed",right:"18px",bottom:"64px",background:"var(--panel)",color:"var(--text)",border:"1px solid var(--border)",boxShadow:"var(--shadow)",padding:"12px",borderRadius:"8px",zIndex:9998,maxWidth:"330px"});document.body.appendChild(d);setTimeout(()=>d.remove(),4200);}
function renderNotifBadge(){const b=$("actionBtn");if(!b)return;const c=notifications().filter(n=>!n.read).length + mail().inbox.filter(m=>!m.read).length;b.textContent="🔔 "+c;}
function defaultFiles(){return [{id:uid(),name:"Welcome to Gold 2.0.edoc",type:"doc",folder:"Documents",content:"<h1>EmeraldOS Gold 2.0</h1><p>Welcome to the friendlier Gold desktop with Support Center, Gold Store verification, logout, staff tools, and improved customization.</p>",star:true,trash:false,created:now(),updated:now()},{id:uid(),name:"Support Guide.edoc",type:"doc",folder:"Support",content:"<h1>Support Guide</h1><p>Use Support Center to submit tickets or request remote assistance.</p>",star:false,trash:false,created:now(),updated:now()}]}
function files(){let f=read(PREFIX+"files",null);if(!f){f=defaultFiles();write(PREFIX+"files",f);}return f}
function saveFiles(f){write(PREFIX+"files",f);saveWorkspaceDebounced();}
function tickets(){return read(PREFIX+"tickets",[])}function saveTickets(t){write(PREFIX+"tickets",t);saveWorkspaceDebounced();}
function mail(){return read(PREFIX+"mail",{inbox:[{id:uid(),from:"system@gold.mail",to:username()+"@gold.mail",subject:"Welcome to EmeraldOS Gold 2.0",body:"Gold Mail is ready.",read:false,time:now()}],sent:[],drafts:[],trash:[]})}
function saveMail(m){write(PREFIX+"mail",m);renderNotifBadge();saveWorkspaceDebounced();}
function storeCatalog(){let s=read(PREFIX+"storeCatalog",null);if(!s){s=STORE_SEED.map(x=>({...x,installed:false,installedByStaff:false,verifiedBy:x.staffVerified?"Emerald Systems Staff":"",reports:0}));write(PREFIX+"storeCatalog",s);}return s}
function saveStore(s){write(PREFIX+"storeCatalog",s);saveWorkspaceDebounced();}
function remoteSessions(){return read(PREFIX+"remoteSessions",[])}function saveRemoteSessions(r){write(PREFIX+"remoteSessions",r);}
function renderDesktop(){const d=$("desktop");if(!d)return;const p=prefs();d.innerHTML=(p.desktopApps||[]).map(id=>{const a=appById(id);return `<div class="desktop-icon" tabindex="0" ondblclick="Gold20.openApp('${a.id}')" onclick="Gold20.clearIconFocus(this)"><img src="${a.logo}" alt=""><span>${esc(a.name)}</span></div>`}).join("");}
function clearIconFocus(el){setTimeout(()=>el.blur(),60)}
function openWindow(id,title,html,opt={}){let existing=$("win_"+id);if(existing){focusWindow(existing);if(existing.classList.contains("min"))existing.classList.remove("min");return existing;}const a=appById(id);const w=document.createElement("section");w.id="win_"+id;w.className="window";w.style.left=(opt.left??(80+Math.random()*80))+"px";w.style.top=(opt.top??(60+Math.random()*70))+"px";w.style.width=(opt.width||900)+"px";w.style.height=(opt.height||620)+"px";w.innerHTML=`<header class="titlebar"><img src="${a.logo}" alt=""><div class="title">${esc(title)}</div><button class="winbtn" onclick="Gold20.minimizeWin('win_${id}')">—</button><button class="winbtn" onclick="Gold20.maximizeWin('win_${id}')">□</button><button class="winbtn close" onclick="Gold20.closeWin('win_${id}')">×</button></header><div class="win-content">${html}</div><div class="resize"></div>`;$("windowLayer").appendChild(w);wireWindow(w);focusWindow(w);renderTaskApps();publishRemoteState();return w;}
function wireWindow(w){w.addEventListener("mousedown",()=>focusWindow(w));const tb=w.querySelector(".titlebar");tb.addEventListener("mousedown",e=>{if(e.target.closest("button"))return;drag={w,x:e.clientX,y:e.clientY,l:w.offsetLeft,t:w.offsetTop};e.preventDefault();});w.querySelector(".resize").addEventListener("mousedown",e=>{resize={w,x:e.clientX,y:e.clientY,w0:w.offsetWidth,h0:w.offsetHeight};e.preventDefault();e.stopPropagation();});}
window.addEventListener("mousemove",e=>{if(drag){drag.w.style.left=Math.max(0,drag.l+e.clientX-drag.x)+"px";drag.w.style.top=Math.max(0,drag.t+e.clientY-drag.y)+"px";} if(resize){resize.w.style.width=Math.max(320,resize.w0+e.clientX-resize.x)+"px";resize.w.style.height=Math.max(220,resize.h0+e.clientY-resize.y)+"px";}});
window.addEventListener("mouseup",()=>{if(drag||resize){publishRemoteState();saveWorkspaceDebounced();}drag=null;resize=null;});
function focusWindow(w){activeWin=w;w.style.zIndex=++z;document.querySelectorAll('.window').forEach(x=>x.classList.toggle('active',x===w));renderTaskApps();}
function minimizeWin(id){const w=$(id);if(w){w.classList.add("min");renderTaskApps();publishRemoteState();}}
function maximizeWin(id){const w=$(id);if(w){w.classList.toggle("max");focusWindow(w);publishRemoteState();}}
function closeWin(id){const w=$(id);if(w){w.remove();renderTaskApps();publishRemoteState();saveWorkspaceDebounced();}}
function renderTaskApps(){const t=$("taskApps");if(!t)return;t.innerHTML=[...document.querySelectorAll('.window')].map(w=>{const id=w.id.replace('win_',''),a=appById(id);return `<button class="task-app ${w===activeWin?'active':''}" onclick="Gold20.taskClick('${w.id}')"><img src="${a.logo}" alt="">${esc(a.name)}</button>`}).join("");}
function taskClick(id){const w=$(id);if(!w)return;if(w.classList.contains('min'))w.classList.remove('min');focusWindow(w);}
function renderTaskbarExtras(){const p=prefs();["searchBtn","staffBtn","supportBtn"].forEach(id=>{const el=$(id);if(!el)return;});$("searchBtn").style.display=p.taskbarSearch?"":"none";$("staffBtn").style.display=p.taskbarStaff?"":"none";$("supportBtn").style.display=p.taskbarSupport?"":"none";}
function toggleStart(){const s=$("startMenu");s.classList.toggle("hidden");if(!s.classList.contains("hidden"))renderStart();}
function renderStart(){const s=$("startMenu");const groups={};APP_DEFS.forEach(a=>(groups[a.category]??=[]).push(a));s.innerHTML=`<div class="start-left"><div class="profile-row"><div class="avatar">${username()[0].toUpperCase()}</div><div><b>${esc(username())}</b><div class="muted">EmeraldOS Gold 2.0</div></div></div><button class="app-row" onclick="Gold20.openApp('settings')">Settings</button><button class="app-row" onclick="Gold20.openApp('support')">Support Center</button><button class="app-row" onclick="Gold20.openApp('store')">Gold Store</button><button class="app-row" onclick="Gold20.logout()">Log out</button><hr>${Object.entries(groups).map(([cat,arr])=>`<h4>${esc(cat)}</h4>${arr.map(a=>`<div class="app-row" onclick="Gold20.openApp('${a.id}')"><img src="${a.logo}">${esc(a.name)}</div>`).join('')}`).join('')}</div><div class="start-right"><h2>Gold 2.0</h2><div class="tiles"><button class="tile gold" onclick="Gold20.openApp('explorer')"><img src="app-logos/explorer.svg">Explorer</button><button class="tile" onclick="Gold20.openApp('office')"><img src="app-logos/office.svg">Office</button><button class="tile green" onclick="Gold20.openApp('support')"><img src="app-logos/support.svg">Support</button><button class="tile purple" onclick="Gold20.openApp('store')"><img src="app-logos/store.svg">Gold Store</button><button class="tile red" onclick="Gold20.openApp('settings')"><img src="app-logos/settings.svg">Settings</button><button class="tile darktile" onclick="Gold20.openApp('staff')"><img src="app-logos/staff.svg">Staff</button></div></div>`;}
function openActionCenter(){const a=$("actionCenter");a.classList.toggle("hidden");if(!a.classList.contains("hidden"))renderActionCenter();}
function renderActionCenter(){const n=notifications();$("actionCenter").innerHTML=`<h2>Action Center</h2><div class="toolbar"><button class="btn" onclick="Gold20.markAllRead()">Mark all read</button><button class="btn" onclick="Gold20.clearNotifications()">Clear all</button></div>${n.map(x=>`<div class="action-card"><b>${esc(x.title)}</b><p>${esc(x.body)}</p><span class="muted">${esc(x.app)} · ${new Date(x.time).toLocaleString()}</span></div>`).join('')||'<p class="muted">No notifications.</p>'}`;}
function markAllRead(){saveNotifications(notifications().map(n=>({...n,read:true})));renderActionCenter();}
function clearNotifications(){saveNotifications([]);renderActionCenter();}
function openSearch(){const p=$("searchPanel");p.classList.toggle("hidden");p.classList.add("search-panel");p.innerHTML=`<h2>Search</h2><input id="searchBox" class="field" placeholder="Search apps, settings, support" oninput="Gold20.search(this.value)" autofocus><div id="searchResults"></div>`;setTimeout(()=>$("searchBox")?.focus(),80);}
function search(q){q=String(q||"").toLowerCase();const arr=APP_DEFS.filter(a=>(a.name+a.category+a.description).toLowerCase().includes(q));$("searchResults").innerHTML=arr.map(a=>`<div class="app-row" onclick="Gold20.openApp('${a.id}')"><img src="${a.logo}"> <div><b>${esc(a.name)}</b><div class="muted">${esc(a.description)}</div></div></div>`).join('')||'<p class="muted">No results.</p>';}
function openTaskView(){const t=$("taskView");t.classList.toggle("hidden");t.innerHTML=`<h2>Task View</h2><div class="grid3">${[...document.querySelectorAll('.window')].map(w=>`<div class="card" onclick="Gold20.taskClick('${w.id}')"><h3>${esc(w.querySelector('.title').textContent)}</h3><p class="muted">${w.classList.contains('min')?'Minimized':'Open'}</p></div>`).join('')||'<p class="muted">No open windows.</p>'}</div><div class="toolbar"><button class="btn" onclick="Gold20.tileWindows()">Tile</button><button class="btn" onclick="Gold20.cascadeWindows()">Cascade</button></div>`;}
function tileWindows(){const wins=[...document.querySelectorAll('.window')];const W=innerWidth,H=innerHeight-52;wins.forEach((w,i)=>{w.classList.remove('max','min');w.style.left=(i%2)*(W/2)+"px";w.style.top=Math.floor(i/2)*(H/Math.ceil(wins.length/2))+"px";w.style.width=(W/2)+"px";w.style.height=(H/Math.ceil(wins.length/2))+"px";});publishRemoteState();}
function cascadeWindows(){[...document.querySelectorAll('.window')].forEach((w,i)=>{w.classList.remove('max','min');w.style.left=(50+i*28)+"px";w.style.top=(40+i*28)+"px";w.style.width="860px";w.style.height="600px";});publishRemoteState();}
function logout(){if(confirm("Log out of EmeraldOS Gold?")){localStorage.removeItem(PREFIX+"loggedIn");localStorage.removeItem("loggedIn");localStorage.removeItem(PREFIX+"staffVerified");location.href="index.html";}}
function openApp(id){$("startMenu")?.classList.add("hidden");const map={explorer:openExplorer,office:openOffice,mail:openMail,chat:openChat,people:openPeople,support:openSupport,store:openStore,settings:openSettings,personalization:openPersonalization,staff:openStaffCenter,remote:openRemoteAssist,security:openSecurity,restore:openRestore,update:openUpdate,notepad:openNotepad,calculator:openCalculator,todo:openTodo,calendar:openCalendar,photos:openPhotos,paint:openPaint,weather:openWeather,clock:openClock,feedback:openFeedback,help:openHelp,bios:()=>location.href='bios.html',dos:openDOS,creator:openCreator,device:openDevice};(map[id]||(()=>openGeneric(id)))();}
function openGeneric(id){const a=appById(id);openWindow(id,a.name,`<div class="app-main"><div class="hero"><h2>${esc(a.name)}</h2><p>${esc(a.description)}</p></div><p>This Gold 2.0 app has a styled shell and can be expanded with additional logic.</p></div>`,{width:720,height:520})}
function openExplorer(){const arr=files();openWindow('explorer','Gold Explorer',`<div class="app-shell"><nav class="app-nav"><button class="active">My Drive</button><button onclick="Gold20.openOffice()">Gold Office</button><button onclick="Gold20.exportFiles()">Export Backup</button></nav><main class="app-main"><div class="hero"><h2>Gold Explorer</h2><p>Manage files, Office documents, starred items, and trash.</p></div><div class="toolbar"><button class="btn primary" onclick="Gold20.newFile()">New File</button><button class="btn" onclick="Gold20.newFolder()">New Folder</button></div><div class="drive-grid">${arr.filter(f=>!f.trash).map(fileCard).join('')}</div><h3>Trash</h3><div class="drive-grid">${arr.filter(f=>f.trash).map(fileCard).join('')||'<p class="muted">Trash is empty.</p>'}</div></main></div>`,{width:1080,height:720})}
function fileCard(f){return `<div class="drive-card"><b>${f.star?'★ ':''}${esc(f.name)}</b><p class="muted">${esc(f.folder)} · ${esc(f.type)} · ${fmtBytes(bytes(f.content||''))}</p><div class="toolbar"><button class="btn small" onclick="Gold20.openFile('${f.id}')">Open</button><button class="btn small" onclick="Gold20.renameFile('${f.id}')">Rename</button><button class="btn small" onclick="Gold20.starFile('${f.id}')">${f.star?'Unstar':'Star'}</button><button class="btn small" onclick="Gold20.trashFile('${f.id}')">${f.trash?'Restore':'Trash'}</button><button class="btn small danger" onclick="Gold20.deleteFile('${f.id}')">Delete</button></div></div>`}
function getFile(id){return files().find(f=>f.id===id)}
function openFile(id){const f=getFile(id);if(!f)return; if(['doc','sheet','slide','form'].includes(f.type))openOffice(f.type,id);else openWindow('file_'+id,f.name,`<div class="app-main"><h2>${esc(f.name)}</h2><textarea class="field" style="min-height:300px" id="fileedit_${id}">${esc(f.content||'')}</textarea><button class="btn primary" onclick="Gold20.savePlainFile('${id}')">Save</button></div>`,{width:720,height:560})}
function savePlainFile(id){const arr=files(),f=arr.find(x=>x.id===id);f.content=$("fileedit_"+id).value;f.updated=now();saveFiles(arr);notify('File saved',f.name,'Gold Explorer');}
function newFile(){const name=prompt('File name','Untitled.edoc');if(!name)return;const ext=(name.split('.').pop()||'txt').toLowerCase();const type=ext==='edoc'?'doc':ext==='esheet'?'sheet':ext==='eslide'?'slide':ext==='eform'?'form':'text';const arr=files();arr.unshift({id:uid(),name,type,folder:'Documents',content:type==='doc'?'<h1>Untitled</h1><p>Start writing.</p>':'',star:false,trash:false,created:now(),updated:now()});saveFiles(arr);openExplorer();}
function newFolder(){const name=prompt('Folder name','New Folder');if(!name)return;const arr=files();arr.unshift({id:uid(),name,type:'folder',folder:'My Drive',content:'',star:false,trash:false,created:now(),updated:now()});saveFiles(arr);openExplorer();}
function renameFile(id){const arr=files(),f=arr.find(x=>x.id===id);const n=prompt('Rename',f.name);if(n){f.name=n;f.updated=now();saveFiles(arr);openExplorer();}}
function starFile(id){const arr=files(),f=arr.find(x=>x.id===id);f.star=!f.star;f.updated=now();saveFiles(arr);openExplorer();}
function trashFile(id){const arr=files(),f=arr.find(x=>x.id===id);f.trash=!f.trash;f.updated=now();saveFiles(arr);openExplorer();}
function deleteFile(id){if(confirm('Delete forever?')){saveFiles(files().filter(f=>f.id!==id));openExplorer();}}
function exportFiles(){saveText('gold20-files.json',JSON.stringify(files(),null,2),'application/json')}
function openOffice(tab='home',fid=null){openWindow('office','Gold Office',officeHTML(tab,fid),{width:1120,height:760})}
function renderOffice(tab,fid){const w=$('win_office');if(!w)return openOffice(tab,fid);w.querySelector('.win-content').innerHTML=officeHTML(tab,fid)}
function officeHTML(tab='home',fid=null){const nav=['home','doc','sheet','slide','form','templates','vault'];return `<div class="app-shell"><nav class="app-nav">${nav.map(n=>`<button class="${tab===n?'active':''}" onclick="Gold20.renderOffice('${n}')">${n[0].toUpperCase()+n.slice(1)}</button>`).join('')}<button onclick="Gold20.openExplorer()">Open Explorer</button></nav><main class="app-main">${officePage(tab,fid)}</main></div>`}
function officePage(tab,fid){const docs=files().filter(f=>['doc','sheet','slide','form'].includes(f.type)&&!f.trash);if(tab==='home')return `<div class="hero"><h2>Gold Office 2.0</h2><p>Drive-integrated Docs, Sheets, Slides, Forms, and templates.</p></div><div class="grid4">${['doc','sheet','slide','form'].map(t=>`<div class="card"><h3>New ${t}</h3><button class="btn primary" onclick="Gold20.officeNew('${t}')">Create</button></div>`).join('')}</div><h3>Recent files</h3><div class="drive-grid">${docs.map(officeCard).join('')}</div>`;if(tab==='templates')return `<h2>Templates</h2><div class="grid3">${['Letter','Memo','Report','Meeting Notes','Policy','Project Plan'].map(t=>`<div class="card"><h3>${t}</h3><button class="btn" onclick="Gold20.templateDoc('${t}')">Use Template</button></div>`).join('')}</div>`;if(tab==='vault')return `<h2>Office Vault</h2><div class="drive-grid">${docs.map(officeCard).join('')}</div>`;if(fid){if(tab==='doc')return docEditor(fid);if(tab==='sheet')return sheetEditor(fid);if(tab==='slide')return slideEditor(fid);if(tab==='form')return formEditor(fid);}return `<h2>${tab}</h2><div class="toolbar"><button class="btn primary" onclick="Gold20.officeNew('${tab}')">New</button></div><div class="drive-grid">${docs.filter(f=>f.type===tab).map(officeCard).join('')||'<p class="muted">No files.</p>'}</div>`}
function officeCard(f){return `<div class="drive-card" onclick="Gold20.renderOffice('${f.type}','${f.id}')"><b>${esc(f.name)}</b><p class="muted">${new Date(f.updated).toLocaleString()}</p></div>`}
function officeNew(type){const name=prompt('Name',type==='doc'?'Untitled.edoc':type==='sheet'?'Untitled.esheet':type==='slide'?'Untitled.eslide':'Untitled.eform');if(!name)return;let content='';if(type==='doc')content='<h1>Untitled</h1><p>Start writing.</p>';if(type==='sheet')content=JSON.stringify([['Item','Amount'],['','']]);if(type==='slide')content=JSON.stringify([{title:'Title',body:'Subtitle'}]);if(type==='form')content=JSON.stringify([{q:'Name',type:'short'}]);const f={id:uid(),name,type,folder:'Office',content,star:false,trash:false,created:now(),updated:now()};const arr=files();arr.unshift(f);saveFiles(arr);renderOffice(type,f.id);}
function templateDoc(t){const f={id:uid(),name:t+'.edoc',type:'doc',folder:'Office',content:`<h1>${esc(t)}</h1><p>Template content for ${esc(t)}.</p>`,star:false,trash:false,created:now(),updated:now()};const arr=files();arr.unshift(f);saveFiles(arr);renderOffice('doc',f.id);}
function saveFileContent(id,content){const arr=files(),f=arr.find(x=>x.id===id);f.content=content;f.updated=now();saveFiles(arr);notify('Saved',f.name,'Gold Office');}
function docEditor(id){const f=getFile(id);return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="document.execCommand('bold')">Bold</button><button class="btn" onclick="document.execCommand('italic')">Italic</button><button class="btn" onclick="document.execCommand('insertUnorderedList')">Bullets</button><button class="btn primary" onclick="Gold20.saveDoc('${id}')">Save</button><button class="btn" onclick="Gold20.exportDoc('${id}')">Export HTML</button></div><div id="doc_${id}" class="editor" contenteditable="true">${f.content||''}</div>`}
function saveDoc(id){saveFileContent(id,$('doc_'+id).innerHTML)}function exportDoc(id){const f=getFile(id);saveText(f.name.replace(/\.edoc$/,'')+'.html',f.content||'','text/html')}
function sheetEditor(id){const f=getFile(id);let rows=[];try{rows=JSON.parse(f.content||'[]')}catch{rows=[['A','B'],['','']]}return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn" onclick="Gold20.sheetAddRow('${id}')">Add Row</button><button class="btn primary" onclick="Gold20.saveSheet('${id}')">Save</button></div><table class="sheet" id="sheet_${id}">${rows.map(r=>`<tr>${r.map(c=>`<td><input value="${esc(c)}"></td>`).join('')}</tr>`).join('')}</table>`}
function saveSheet(id){const rows=[...document.querySelectorAll('#sheet_'+id+' tr')].map(tr=>[...tr.querySelectorAll('input')].map(i=>i.value));saveFileContent(id,JSON.stringify(rows));}
function sheetAddRow(id){const table=$('sheet_'+id);const cols=table.rows[0]?.cells.length||2;const tr=table.insertRow();for(let i=0;i<cols;i++)tr.insertCell().innerHTML='<input value="">';}
function slideEditor(id){const f=getFile(id);let slides=[];try{slides=JSON.parse(f.content||'[]')}catch{slides=[{title:'Title',body:'Body'}]}return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn primary" onclick="Gold20.saveSlides('${id}')">Save</button><button class="btn" onclick="Gold20.addSlide('${id}')">Add Slide</button></div><div id="slides_${id}">${slides.map((s,i)=>`<div class="card"><b>Slide ${i+1}</b><input class="field" value="${esc(s.title)}"><textarea class="field">${esc(s.body)}</textarea></div>`).join('')}</div>`}
function saveSlides(id){const slides=[...document.querySelectorAll('#slides_'+id+' .card')].map(c=>({title:c.querySelector('input').value,body:c.querySelector('textarea').value}));saveFileContent(id,JSON.stringify(slides));}
function addSlide(id){$('slides_'+id).insertAdjacentHTML('beforeend','<div class="card"><b>New Slide</b><input class="field" value="Title"><textarea class="field">Body</textarea></div>')}
function formEditor(id){const f=getFile(id);let qs=[];try{qs=JSON.parse(f.content||'[]')}catch{qs=[{q:'Question',type:'short'}]}return `<h2>${esc(f.name)}</h2><div class="toolbar"><button class="btn primary" onclick="Gold20.saveForm('${id}')">Save</button><button class="btn" onclick="Gold20.addQuestion('${id}')">Add Question</button></div><div id="form_${id}">${qs.map(q=>`<div class="card"><input class="field" value="${esc(q.q)}"><select class="field"><option>short</option><option>paragraph</option><option>multiple choice</option></select></div>`).join('')}</div>`}
function saveForm(id){const qs=[...document.querySelectorAll('#form_'+id+' .card')].map(c=>({q:c.querySelector('input').value,type:c.querySelector('select').value}));saveFileContent(id,JSON.stringify(qs));}
function addQuestion(id){$('form_'+id).insertAdjacentHTML('beforeend','<div class="card"><input class="field" value="New question"><select class="field"><option>short</option><option>paragraph</option><option>multiple choice</option></select></div>')}
function openSupport(){const mine=tickets().filter(t=>t.user===username());openWindow('support','Support Center',`<div class="app-shell"><nav class="app-nav"><button class="active">Tickets</button><button onclick="Gold20.openRemoteAssist()">Remote Assistance</button><button onclick="Gold20.openHelp()">Help Articles</button></nav><main class="app-main"><div class="hero"><h2>Support Center</h2><p>Submit tickets, request remote help, and view staff replies.</p></div><div class="grid2"><div class="card"><h3>New Ticket</h3><input id="ticketSubject" class="field" placeholder="Subject"><select id="ticketCategory" class="field"><option>General Support</option><option>Account/Login</option><option>Office</option><option>Store/App</option><option>Remote Assistance</option></select><select id="ticketPriority" class="field"><option>Normal</option><option>High</option><option>Urgent</option></select><textarea id="ticketBody" class="field" placeholder="Describe the issue"></textarea><button class="btn primary" onclick="Gold20.submitTicket()">Submit Ticket</button></div><div class="card"><h3>Remote Help</h3><p>Request staff help. You stay in control and can end access anytime.</p><button class="btn" onclick="Gold20.requestRemote()">Request Remote Help</button><button class="btn" onclick="Gold20.endRemote()">End Remote</button></div></div><h3>Your Tickets</h3>${mine.map(ticketCard).join('')||'<p class="muted">No tickets yet.</p>'}</main></div>`,{width:1060,height:720})}
function ticketCard(t){return `<div class="card ticket status-${esc(t.status||'open').toLowerCase()}"><h3>#${esc(t.id)} · ${esc(t.subject)}</h3><p>${esc(t.body)}</p><p><span class="badge">${esc(t.status||'Open')}</span> <span class="badge">${esc(t.priority)}</span> <span class="muted">${new Date(t.time).toLocaleString()}</span></p>${(t.replies||[]).map(r=>`<div class="notice"><b>${esc(r.from)}:</b> ${esc(r.body)}<br><small>${new Date(r.time).toLocaleString()}</small></div>`).join('')}</div>`}
function submitTicket(){const t={id:String(tickets().length+1).padStart(4,'0'),user:username(),subject:$('ticketSubject').value||'Support Request',category:$('ticketCategory').value,priority:$('ticketPriority').value,body:$('ticketBody').value||'',status:'Open',time:now(),replies:[]};saveTickets([t,...tickets()]);notify('Ticket submitted','#'+t.id+' '+t.subject,'Support Center');openSupport();}
function requestRemote(){const s={id:uid(),user:username(),status:'requested',controlGranted:true,time:now(),state:snapshotState(),commands:[]};saveRemoteSessions([s,...remoteSessions().filter(x=>x.user!==username())]);localStorage.setItem(PREFIX+'remoteActive',s.id);showRemoteBanner();notify('Remote assistance requested','Staff can view your live desktop state after approval.','Support Center');publishRemoteState();}
function endRemote(){const id=localStorage.getItem(PREFIX+'remoteActive');saveRemoteSessions(remoteSessions().map(r=>r.id===id?{...r,status:'ended',ended:now()}:r));localStorage.removeItem(PREFIX+'remoteActive');document.querySelector('.remote-banner')?.remove();notify('Remote assistance ended','Staff remote control was stopped.','Support Center');}
function showRemoteBanner(){if(document.querySelector('.remote-banner'))return;const b=document.createElement('div');b.className='remote-banner';b.innerHTML='Staff remote assistance active <button class="btn small" onclick="Gold20.endRemote()">End</button>';document.body.appendChild(b);}
function snapshotState(){return {user:username(),time:now(),openWindows:[...document.querySelectorAll('.window')].map(w=>({id:w.id,title:w.querySelector('.title')?.textContent||'',min:w.classList.contains('min'),max:w.classList.contains('max')})),desktop:prefs().desktopApps,notifications:notifications().slice(0,8),files:files().slice(0,8).map(f=>({name:f.name,type:f.type,star:f.star}))}}
function publishRemoteState(){const id=localStorage.getItem(PREFIX+'remoteActive');if(!id)return;const arr=remoteSessions().map(r=>r.id===id?{...r,state:snapshotState(),lastUpdate:now()}:r);saveRemoteSessions(arr);}
function openRemoteAssist(){const active=remoteSessions().find(r=>r.id===localStorage.getItem(PREFIX+'remoteActive'));openWindow('remote','Remote Assist',`<div class="app-main"><div class="hero"><h2>Remote Assist</h2><p>Staff can view your desktop state and send safe commands only after you request help.</p></div><p>Status: <span class="badge">${active?esc(active.status):'Not active'}</span></p><button class="btn primary" onclick="Gold20.requestRemote()">Request Remote Help + Grant Control</button><button class="btn danger" onclick="Gold20.endRemote()">End Remote Control</button></div>`,{width:650,height:480})}
function openStore(){const s=storeCatalog();openWindow('store','Gold Store',`<div class="app-shell"><nav class="app-nav"><button class="active">Store Home</button><button onclick="Gold20.storeFilter('installed')">Installed</button><button onclick="Gold20.storeFilter('verified')">Staff Verified</button><button onclick="Gold20.openApp('staff')">Staff Review</button></nav><main class="app-main"><div class="hero"><h2>Gold Store 2.0</h2><p>Install Gold apps, see Staff Verified marks, and report unsafe apps.</p></div><div class="store-grid">${s.map(storeCard).join('')}</div></main></div>`,{width:1120,height:720})}
function storeCard(a){return `<div class="store-card"><div class="logo-card"><img src="app-logos/store.svg"><div><h3>${esc(a.name)}</h3><p class="muted">${esc(a.category)} · v${esc(a.version)}</p></div></div><p>${esc(a.description)}</p><p>${a.staffVerified?'<span class="badge verified">✓ Staff Verified</span>':'<span class="badge">Unverified</span>'} ${a.installedByStaff?'<span class="badge staff">Installed by Staff</span>':''}</p><div class="toolbar"><button class="btn primary" onclick="Gold20.installStoreApp('${a.id}')">${a.installed?'Open':'Install'}</button><button class="btn" onclick="Gold20.reportStoreApp('${a.id}')">Report</button></div></div>`}
function installStoreApp(id){const arr=storeCatalog(),a=arr.find(x=>x.id===id);if(!a)return;if(!a.installed){a.installed=true;a.installedAt=now();notify('App installed',a.name+(a.staffVerified?' is Staff Verified':''),'Gold Store');}else notify('Opening app',a.name,'Gold Store');saveStore(arr);openStore();}
function reportStoreApp(id){const arr=storeCatalog(),a=arr.find(x=>x.id===id);a.reports=(a.reports||0)+1;saveStore(arr);notify('App reported',a.name,'Gold Store');openStore();}
function storeFilter(kind){const s=storeCatalog().filter(a=>kind==='installed'?a.installed:a.staffVerified);openWindow('store','Gold Store',`<div class="app-main"><h2>${kind==='installed'?'Installed Apps':'Staff Verified Apps'}</h2><div class="store-grid">${s.map(storeCard).join('')||'<p class="muted">None.</p>'}</div></div>`,{width:980,height:650})}
function openSettings(section='system'){const secs=['system','personalization','apps','accounts','support','store','privacy','accessibility','update','staff','about'];openWindow('settings','Settings',`<div class="app-shell"><nav class="app-nav">${secs.map(s=>`<button class="${s===section?'active':''}" onclick="Gold20.renderSettings('${s}')">${s[0].toUpperCase()+s.slice(1)}</button>`).join('')}</nav><main class="app-main" id="settingsBody">${settingsPage(section)}</main></div>`,{width:1000,height:720})}
function renderSettings(s){const body=$('settingsBody'); if(body) body.innerHTML=settingsPage(s);}
function settingsPage(s){const p=prefs();if(s==='personalization')return `<h2>Personalization</h2><label>Theme<select class="field" onchange="Gold20.setPrefs({theme:this.value})"><option ${p.theme==='light'?'selected':''}>light</option><option ${p.theme==='dark'?'selected':''}>dark</option><option ${p.theme==='highcontrast'?'selected':''}>highcontrast</option></select></label><label>Accent Color<input type="color" class="field" value="${esc(p.accent)}" onchange="Gold20.setPrefs({accent:this.value})"></label><label>Background URL<input class="field" placeholder="https://..." value="${esc(p.customBackground)}" onchange="Gold20.setPrefs({customBackground:this.value})"></label><div class="toolbar"><button class="btn" onclick="Gold20.setPrefs({background:'gold',customBackground:''})">Gold</button><button class="btn" onclick="Gold20.setPrefs({background:'blue',customBackground:''})">Blue</button><button class="btn" onclick="Gold20.setPrefs({background:'emerald',customBackground:''})">Emerald</button><button class="btn" onclick="Gold20.setPrefs({background:'slate',customBackground:''})">Slate</button></div><label>Icon Size<select class="field" onchange="Gold20.setPrefs({iconSize:this.value})"><option>small</option><option selected>normal</option><option>large</option></select></label><button class="btn" onclick="Gold20.toggleLabels()">Toggle desktop labels</button>`;if(s==='apps')return `<h2>Apps</h2><p>Choose which apps appear on the desktop.</p><div class="grid3">${APP_DEFS.map(a=>`<label class="card"><input type="checkbox" ${p.desktopApps.includes(a.id)?'checked':''} onchange="Gold20.toggleDesktopApp('${a.id}',this.checked)"> <img src="${a.logo}" style="width:28px"> ${esc(a.name)}</label>`).join('')}</div>`;if(s==='accounts')return `<h2>Accounts</h2><p>Signed in as <b>${esc(username())}</b></p><button class="btn danger" onclick="Gold20.logout()">Log out</button>`;if(s==='support')return `<h2>Support</h2><button class="btn primary" onclick="Gold20.openSupport()">Open Support Center</button><button class="btn" onclick="Gold20.openRemoteAssist()">Remote Assistance</button>`;if(s==='store')return `<h2>Gold Store</h2><button class="btn primary" onclick="Gold20.openStore()">Open Gold Store</button><button class="btn" onclick="Gold20.storeFilter('verified')">View Staff Verified Apps</button>`;if(s==='staff')return `<h2>Staff</h2><p>Staff tools require verified staff access.</p><button class="btn primary" onclick="Gold20.openStaffCenter()">Open Staff Center</button><button class="btn" onclick="location.href='staff.html'">Staff Login Page</button>`;if(s==='accessibility')return `<h2>Accessibility</h2><label><input type="checkbox" ${p.bigText?'checked':''} onchange="Gold20.setPrefs({bigText:this.checked})"> Larger text</label><br><label><input type="checkbox" ${p.reducedMotion?'checked':''} onchange="Gold20.setPrefs({reducedMotion:this.checked})"> Reduced motion</label><br><label><input type="checkbox" ${p.highContrast?'checked':''} onchange="Gold20.setPrefs({highContrast:this.checked})"> High contrast</label>`;if(s==='about')return `<h2>About</h2><p>EmeraldOS Gold 2.0</p><p class="muted">Support, Gold Store, Staff Verified apps, logout, user-friendly desktop, and Windows 10-inspired EmeraldOS Gold UI.</p>`;return `<h2>System</h2><div class="grid2"><div class="card"><h3>Display</h3><button class="btn" onclick="Gold20.tileWindows()">Tile windows</button><button class="btn" onclick="Gold20.cascadeWindows()">Cascade windows</button></div><div class="card"><h3>Taskbar</h3><label><input type="checkbox" ${p.taskbarSearch?'checked':''} onchange="Gold20.setPrefs({taskbarSearch:this.checked})"> Search box</label><br><label><input type="checkbox" ${p.taskbarSupport?'checked':''} onchange="Gold20.setPrefs({taskbarSupport:this.checked})"> Support button</label><br><label><input type="checkbox" ${p.taskbarStaff?'checked':''} onchange="Gold20.setPrefs({taskbarStaff:this.checked})"> Staff button</label></div></div>`;}
function toggleLabels(){setPrefs({labels:!prefs().labels})}
function toggleDesktopApp(id,on){const p=prefs();let d=[...p.desktopApps];if(on&&!d.includes(id))d.push(id);if(!on)d=d.filter(x=>x!==id);setPrefs({desktopApps:d})}
function openPersonalization(){openSettings('personalization')}
function openStaffCenter(){if(!isStaff()){openWindow('staff','Staff Access Required',`<div class="app-main"><h2>Staff access required</h2><p>Staff tools are restricted. Sign in through Gold Staff Edition.</p><button class="btn primary" onclick="location.href='staff.html'">Open Staff Login</button></div>`,{width:560,height:360});return;}const t=tickets(),r=remoteSessions(),s=storeCatalog();openWindow('staff','Gold Staff Center',`<div class="app-shell"><nav class="app-nav"><button class="active">Dashboard</button><button onclick="Gold20.staffTickets()">Tickets</button><button onclick="Gold20.staffStore()">Store Verification</button><button onclick="Gold20.staffRemote()">Remote Desktop</button></nav><main class="app-main"><div class="hero"><h2>Gold Staff Center</h2><p>Staff-only support, Gold Store verification, and live remote desktop tools.</p></div><div class="grid3"><div class="card"><h3>${t.length}</h3><p>Tickets</p></div><div class="card"><h3>${r.filter(x=>x.status!=='ended').length}</h3><p>Remote sessions</p></div><div class="card"><h3>${s.filter(x=>x.staffVerified).length}</h3><p>Staff Verified apps</p></div></div></main></div>`,{width:1120,height:740})}
function staffTickets(){const body=document.querySelector('#win_staff .win-content .app-main');if(body)body.innerHTML=`<h2>Support Tickets</h2>${tickets().map(t=>`<div class="card ticket"><h3>#${t.id} · ${esc(t.subject)} · ${esc(t.user)}</h3><p>${esc(t.body)}</p><p><span class="badge">${esc(t.status)}</span> <span class="badge">${esc(t.priority)}</span></p><textarea class="field" id="reply_${t.id}" placeholder="Staff reply"></textarea><button class="btn primary" onclick="Gold20.staffReply('${t.id}')">Reply</button><button class="btn" onclick="Gold20.staffResolve('${t.id}')">Resolve</button></div>`).join('')||'<p>No tickets.</p>'}`;}
function staffReply(id){const arr=tickets();const t=arr.find(x=>x.id===id);t.replies=t.replies||[];t.replies.push({from:'Gold Staff',body:document.getElementById('reply_'+id).value||'Staff reviewed this ticket.',time:now()});saveTickets(arr);notify('Staff replied to ticket','#'+id,'Support Center');staffTickets();}
function staffResolve(id){const arr=tickets();const t=arr.find(x=>x.id===id);t.status='Resolved';saveTickets(arr);staffTickets();}
function staffStore(){const body=document.querySelector('#win_staff .win-content .app-main');if(body)body.innerHTML=`<h2>Gold Store Verification</h2><div class="store-grid">${storeCatalog().map(a=>`<div class="store-card"><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><p>${a.staffVerified?'<span class="badge verified">✓ Staff Verified</span>':'<span class="badge">Unverified</span>'} ${a.installedByStaff?'<span class="badge staff">Installed by Staff</span>':''}</p><button class="btn primary" onclick="Gold20.staffVerifyApp('${a.id}')">Toggle Staff Verified</button><button class="btn" onclick="Gold20.staffInstallApp('${a.id}')">Mark Installed by Staff</button></div>`).join('')}</div>`;}
function staffVerifyApp(id){const arr=storeCatalog(),a=arr.find(x=>x.id===id);a.staffVerified=!a.staffVerified;a.verifiedBy=a.staffVerified?username():'';saveStore(arr);staffStore();}
function staffInstallApp(id){const arr=storeCatalog(),a=arr.find(x=>x.id===id);a.installed=true;a.installedByStaff=true;a.staffVerified=true;a.verifiedBy=username();saveStore(arr);notify('Staff installed and verified app',a.name,'Gold Store');staffStore();}
function staffRemote(){const body=document.querySelector('#win_staff .win-content .app-main');if(body)body.innerHTML=`<h2>Live Remote Desktop</h2>${remoteSessions().map(r=>`<div class="card"><h3>${esc(r.user)} · ${esc(r.status)}</h3><div class="remote-live">${esc(JSON.stringify(r.state,null,2))}</div><div class="toolbar"><button class="btn" onclick="Gold20.remoteCommand('${r.id}','openSupport')">Open Support</button><button class="btn" onclick="Gold20.remoteCommand('${r.id}','openSettings')">Open Settings</button><button class="btn" onclick="Gold20.remoteCommand('${r.id}','tile')">Tile Windows</button><button class="btn danger" onclick="Gold20.remoteCommand('${r.id}','end')">End</button></div></div>`).join('')||'<p>No remote sessions.</p>'}`;}
function remoteCommand(id,cmd){const arr=remoteSessions(),r=arr.find(x=>x.id===id);r.commands=[...(r.commands||[]),{cmd,by:username(),time:now()}];if(cmd==='end')r.status='ended';saveRemoteSessions(arr);staffRemote();}
function runRemoteCommands(){const id=localStorage.getItem(PREFIX+'remoteActive');if(!id)return;const arr=remoteSessions();const r=arr.find(x=>x.id===id);if(!r)return;const cmds=r.commands||[];cmds.splice(0).forEach(c=>{if(c.cmd==='openSupport')openSupport();if(c.cmd==='openSettings')openSettings();if(c.cmd==='tile')tileWindows();if(c.cmd==='end')endRemote();});saveRemoteSessions(arr);}
function openMail(){const m=mail();openWindow('mail','Gold Mail',`<div class="app-shell"><nav class="app-nav"><button class="active">Inbox</button><button onclick="Gold20.composeMail()">Compose</button><button onclick="Gold20.mailFolder('sent')">Sent</button><button onclick="Gold20.mailFolder('drafts')">Drafts</button><button onclick="Gold20.mailFolder('trash')">Trash</button></nav><main class="app-main"><h2>Inbox</h2>${m.inbox.map(msgCard).join('')||'<p>No mail.</p>'}</main></div>`,{width:1020,height:700})}
function msgCard(m){return `<div class="card"><h3>${m.read?'':'● '}${esc(m.subject)}</h3><p class="muted">From: ${esc(m.from)} · ${new Date(m.time).toLocaleString()}</p><p>${esc(m.body)}</p><button class="btn" onclick="Gold20.replyMail('${m.id}')">Reply</button></div>`}
function composeMail(){openWindow('compose','Compose Mail',`<div class="app-main"><h2>Compose</h2><input id="mailTo" class="field" placeholder="To"><input id="mailSubject" class="field" placeholder="Subject"><textarea id="mailBody" class="field" style="min-height:220px" placeholder="Message"></textarea><button class="btn primary" onclick="Gold20.sendMail()">Send</button><button class="btn" onclick="Gold20.saveDraft()">Save Draft</button></div>`,{width:620,height:560})}
function sendMail(){const m=mail();m.sent.unshift({id:uid(),from:username()+'@gold.mail',to:$('mailTo').value,subject:$('mailSubject').value,body:$('mailBody').value,read:true,time:now()});saveMail(m);notify('Mail sent',$('mailSubject').value,'Gold Mail');closeWin('win_compose');openMail();}
function saveDraft(){const m=mail();m.drafts.unshift({id:uid(),to:$('mailTo').value,subject:$('mailSubject').value,body:$('mailBody').value,time:now()});saveMail(m);notify('Draft saved',$('mailSubject').value,'Gold Mail')}
function mailFolder(folder){const m=mail();openWindow('mail','Gold Mail',`<div class="app-main"><h2>${folder}</h2>${(m[folder]||[]).map(msgCard).join('')||'<p>No messages.</p>'}</div>`,{width:900,height:620})}
function replyMail(id){const msg=mail().inbox.find(x=>x.id===id);composeMail();setTimeout(()=>{$('mailTo').value=msg.from;$('mailSubject').value='Re: '+msg.subject;},50)}
function openChat(){openWindow('chat','Gold Chat',`<div class="app-main"><h2>Gold Chat</h2><div id="chatLog" class="card" style="height:320px;overflow:auto">${read(PREFIX+'chat',[]).map(c=>`<p><b>${esc(c.from)}:</b> ${esc(c.text)}</p>`).join('')}</div><input id="chatInput" class="field" placeholder="Message"><button class="btn primary" onclick="Gold20.sendChat()">Send</button></div>`,{width:680,height:540})}
function sendChat(){const arr=read(PREFIX+'chat',[]);arr.push({from:username(),text:$('chatInput').value,time:now()});write(PREFIX+'chat',arr);openChat();}
function openPeople(){openWindow('people','People',`<div class="app-main"><h2>People</h2><div class="grid3">${['Gold Staff','Support Desk','Emerald Systems','Wyatt Monroe'].map(n=>`<div class="card"><h3>${n}</h3><p>${n.toLowerCase().replaceAll(' ','.')}@gold.mail</p><button class="btn" onclick="Gold20.openMail()">Mail</button><button class="btn" onclick="Gold20.openChat()">Chat</button></div>`).join('')}</div></div>`,{width:900,height:600})}
function openNotepad(){openWindow('notepad','Notepad',`<div class="app-main"><textarea id="notepadText" class="field" style="min-height:380px">${esc(read(PREFIX+'notepad',''))}</textarea><button class="btn primary" onclick="Gold20.saveNotepad()">Save</button><button class="btn" onclick="Gold20.exportNotepad()">Export</button></div>`,{width:700,height:560})}function saveNotepad(){write(PREFIX+'notepad',$('notepadText').value);notify('Saved','Notepad saved','Notepad')}function exportNotepad(){saveText('gold-notepad.txt',$('notepadText').value)}
function openCalculator(){openWindow('calculator','Calculator',`<div class="app-main"><input id="calc" class="field" placeholder="2+2"><button class="btn primary" onclick="Gold20.calcRun()">Calculate</button><h2 id="calcOut"></h2></div>`,{width:420,height:320})}function calcRun(){try{$('calcOut').textContent=Function('return ('+$('calc').value+')')()}catch{$('calcOut').textContent='Error'}}
function openTodo(){const arr=read(PREFIX+'todo',[]);openWindow('todo','Gold To Do',`<div class="app-main"><h2>To Do</h2><input id="todoNew" class="field" placeholder="New task"><button class="btn primary" onclick="Gold20.addTodo()">Add</button>${arr.map((t,i)=>`<div class="card"><label><input type="checkbox" ${t.done?'checked':''} onchange="Gold20.toggleTodo(${i})"> ${esc(t.text)}</label></div>`).join('')}</div>`,{width:600,height:540})}function addTodo(){const arr=read(PREFIX+'todo',[]);arr.push({text:$('todoNew').value,done:false});write(PREFIX+'todo',arr);openTodo();}function toggleTodo(i){const arr=read(PREFIX+'todo',[]);arr[i].done=!arr[i].done;write(PREFIX+'todo',arr);openTodo();}
function openPaint(){openWindow('paint','Gold Paint',`<div class="app-main"><h2>Gold Paint</h2><canvas id="paintCanvas" width="680" height="360" style="background:white;border:1px solid var(--border)"></canvas><p class="muted">Drag to draw. Use Export to save image.</p><button class="btn" onclick="Gold20.clearPaint()">Clear</button><button class="btn" onclick="Gold20.exportPaint()">Export</button></div>`,{width:780,height:600});setTimeout(initPaint,50)}function initPaint(){const c=$('paintCanvas');if(!c)return;const ctx=c.getContext('2d');let draw=false;c.onmousedown=e=>{draw=true;ctx.beginPath();ctx.moveTo(e.offsetX,e.offsetY)};c.onmousemove=e=>{if(draw){ctx.lineTo(e.offsetX,e.offsetY);ctx.stroke();}};c.onmouseup=()=>draw=false;}function clearPaint(){const c=$('paintCanvas');c.getContext('2d').clearRect(0,0,c.width,c.height)}function exportPaint(){const a=document.createElement('a');a.download='gold-paint.png';a.href=$('paintCanvas').toDataURL();a.click();}
function openCalendar(){openGeneric('calendar')}function openPhotos(){openGeneric('photos')}function openWeather(){openGeneric('weather')}function openClock(){openGeneric('clock')}function openFeedback(){openWindow('feedback','Feedback Hub',`<div class="app-main"><h2>Feedback Hub</h2><textarea id="fbText" class="field" placeholder="Tell us what to improve"></textarea><button class="btn primary" onclick="Gold20.submitFeedback()">Submit</button></div>`,{width:600,height:480})}function submitFeedback(){const arr=read(PREFIX+'feedback',[]);arr.unshift({user:username(),body:$('fbText').value,time:now()});write(PREFIX+'feedback',arr);notify('Feedback sent','Thank you','Feedback Hub');}
function openHelp(){openWindow('help','Help and Support',`<div class="app-main"><h2>Help and Support</h2><div class="grid2"><div class="card"><h3>Use Support Center</h3><p>Submit a ticket and staff can reply.</p></div><div class="card"><h3>Gold Store</h3><p>Look for Staff Verified badges before installing apps.</p></div><div class="card"><h3>Remote Assistance</h3><p>Only starts after you request it. End control anytime.</p></div><div class="card"><h3>Logout</h3><p>Use the power button on the taskbar or Start menu.</p></div></div></div>`,{width:820,height:560})}
function openSecurity(){openWindow('security','Security Center',`<div class="app-main"><h2>Security Center</h2><p class="badge verified">Staff Verified app badges are enabled</p><p>Remote assistance requires user request and shows a red banner.</p></div>`,{width:680,height:480})}
function openRestore(){openWindow('restore','Restore Center',`<div class="app-main"><h2>Restore Center</h2><button class="btn primary" onclick="Gold20.saveWorkspaceNow()">Save Workspace</button><button class="btn" onclick="Gold20.restoreWorkspace()">Restore Workspace</button><button class="btn" onclick="Gold20.exportWorkspace()">Export Backup</button><button class="btn danger" onclick="Gold20.resetGold()">Reset Local Gold Data</button></div>`,{width:650,height:480})}
function openUpdate(){openWindow('update','Update Center',`<div class="app-main"><h2>Update Center</h2><p>EmeraldOS Gold 2.0 is installed.</p><span class="badge verified">Current</span></div>`,{width:600,height:420})}
function openCreator(){openGeneric('creator')}function openDevice(){openGeneric('device')}
function openDOS(){openWindow('dos','Emerald DOS',`<div class="app-main"><div id="dosOut" class="dos">Emerald DOS Gold 2.0\nType HELP.\n</div><input id="dosIn" class="field" onkeydown="if(event.key==='Enter')Gold20.dosRun(this.value)"></div>`,{width:760,height:520})}
function dosRun(cmd){cmd=String(cmd).trim().toUpperCase();const out=$('dosOut');out.textContent+='> '+cmd+'\n';if(cmd==='HELP')out.textContent+='BOOT STAFF SUPPORT STORE SETTINGS VER DIR LOGOUT CLEAR\n';else if(cmd==='VER')out.textContent+=BUILD.name+'\n';else if(cmd==='DIR')out.textContent+=APP_DEFS.map(a=>a.name).join('\n')+'\n';else if(cmd==='STAFF')location.href='staff.html';else if(cmd==='SUPPORT')openSupport();else if(cmd==='STORE')openStore();else if(cmd==='SETTINGS')openSettings();else if(cmd==='LOGOUT')logout();else if(cmd==='CLEAR')out.textContent='';else out.textContent+='Unknown command\n';$('dosIn').value='';}
function saveWorkspaceNow(){const state={prefs:prefs(),files:files(),tickets:tickets(),mail:mail(),store:storeCatalog(),notifications:notifications(),time:now()};write(PREFIX+'workspace',state);notify('Workspace saved','Local workspace backup updated','Restore Center');}
function restoreWorkspace(){const s=read(PREFIX+'workspace',null);if(!s)return alert('No backup found');Object.entries({prefs:s.prefs,files:s.files,tickets:s.tickets,mail:s.mail,storeCatalog:s.store,notifications:s.notifications}).forEach(([k,v])=>{if(v)localStorage.setItem(PREFIX+(k==='storeCatalog'?'storeCatalog':k),JSON.stringify(v));});applyPrefs();renderDesktop();notify('Workspace restored','Gold restored from local backup','Restore Center');}
function exportWorkspace(){saveText('emeraldos-gold20-workspace.json',JSON.stringify({prefs:prefs(),files:files(),tickets:tickets(),mail:mail(),store:storeCatalog()},null,2),'application/json')}
function resetGold(){if(confirm('Reset local Gold 2.0 data?')){Object.keys(localStorage).filter(k=>k.startsWith(PREFIX)&&!k.includes('loggedIn')).forEach(k=>localStorage.removeItem(k));location.reload();}}
function saveWorkspaceDebounced(){clearTimeout(workspaceTimer);workspaceTimer=setTimeout(saveWorkspaceNow,1200)}
function setupWizard(){if(localStorage.getItem(PREFIX+'setupDone'))return;const w=$('setupWizard');w.classList.remove('hidden');w.innerHTML=`<div class="setup-card"><h1>Set up EmeraldOS Gold 2.0</h1><p>Choose a friendly desktop setup.</p><label>Theme<select id="setupTheme" class="field"><option value="light">Light</option><option value="dark">Dark</option></select></label><label>Desktop style<select id="setupStyle" class="field"><option value="default">Default</option><option value="support">Support-focused</option><option value="productivity">Productivity</option></select></label><button class="btn primary" onclick="Gold20.finishSetup()">Finish Setup</button></div>`;}
function finishSetup(){setPrefs({theme:$('setupTheme').value});localStorage.setItem(PREFIX+'setupDone','true');$('setupWizard').classList.add('hidden');notify('Setup complete','Welcome to EmeraldOS Gold 2.0','Setup');}
function clockTick(){const d=new Date();$('clock').textContent=d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:prefs().clockSeconds?'2-digit':undefined});}
function initEvents(){$('startBtn').onclick=toggleStart;$('searchBtn').onclick=openSearch;$('taskViewBtn').onclick=openTaskView;$('actionBtn').onclick=openActionCenter;$('supportBtn').onclick=()=>openSupport();$('staffBtn').onclick=()=>openStaffCenter();$('logoutBtn').onclick=logout;window.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key===' '){e.preventDefault();openSearch();}if(e.altKey&&e.key.toLowerCase()==='s')openSupport();if(e.altKey&&e.key.toLowerCase()==='x')logout();})}
function init(){applyPrefs();renderDesktop();renderTaskbarExtras();initEvents();initFirebase();setTimeout(()=>$('boot')?.classList.add('fade'),950);setupWizard();renderNotifBadge();clockTick();setInterval(clockTick,1000);setInterval(runRemoteCommands,1200);setInterval(publishRemoteState,2500);const bootApp=localStorage.getItem(PREFIX+'open_on_boot');if(bootApp){localStorage.removeItem(PREFIX+'open_on_boot');setTimeout(()=>openApp(bootApp),1200);}}
window.Gold20={openApp,clearIconFocus,minimizeWin,maximizeWin,closeWin,taskClick,toggleStart,openActionCenter,markAllRead,clearNotifications,openSearch,search,openTaskView,tileWindows,cascadeWindows,logout,openExplorer,openFile,savePlainFile,newFile,newFolder,renameFile,starFile,trashFile,deleteFile,exportFiles,openOffice,renderOffice,officeNew,templateDoc,saveDoc,exportDoc,sheetAddRow,saveSheet,saveSlides,addSlide,saveForm,addQuestion,openSupport,submitTicket,requestRemote,endRemote,openRemoteAssist,openStore,installStoreApp,reportStoreApp,storeFilter,openSettings,renderSettings,setPrefs,toggleLabels,toggleDesktopApp,openPersonalization,openStaffCenter,staffTickets,staffReply,staffResolve,staffStore,staffVerifyApp,staffInstallApp,staffRemote,remoteCommand,openMail,composeMail,sendMail,saveDraft,mailFolder,replyMail,openChat,sendChat,openPeople,openNotepad,saveNotepad,exportNotepad,openCalculator,calcRun,openTodo,addTodo,toggleTodo,openPaint,clearPaint,exportPaint,openCalendar,openPhotos,openWeather,openClock,openFeedback,submitFeedback,openHelp,openSecurity,openRestore,openUpdate,openCreator,openDevice,openDOS,dosRun,saveWorkspaceNow,restoreWorkspace,exportWorkspace,resetGold,finishSetup};
window.addEventListener('DOMContentLoaded',init);
})();